import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract watermark high_ts scalar
    if len(watermark) > 0:
        high_ts = watermark["high_ts"].iloc[0]
    else:
        high_ts = None

    # Ensure proper dtypes for timestamps
    if not pd.api.types.is_datetime64_any_dtype(target_snapshot["status_ts"]):
        target_snapshot["status_ts"] = pd.to_datetime(target_snapshot["status_ts"])
    if not pd.api.types.is_datetime64_any_dtype(cdc_events["event_ts"]):
        cdc_events["event_ts"] = pd.to_datetime(cdc_events["event_ts"])
    if high_ts is not None and not isinstance(high_ts, pd.Timestamp):
        high_ts = pd.to_datetime(high_ts)

    # Build initial state dict keyed by user_id from target_snapshot
    # If duplicate user_id rows exist, later rows (as they appear in the
    # dataframe) overwrite earlier ones.
    state = {}
    for row in target_snapshot.itertuples(index=False):
        state[row.user_id] = {
            "email": row.email,
            "status": row.status,
            "status_ts": row.status_ts,
        }

    # Filter cdc events strictly after watermark
    if high_ts is not None:
        filtered = cdc_events[cdc_events["event_ts"] > high_ts].copy()
    else:
        filtered = cdc_events.copy()

    # Sort by (event_ts, event_seq) to apply sequentially across all users
    filtered = filtered.sort_values(by=["event_ts", "event_seq"], kind="mergesort")

    seven_days = pd.Timedelta(days=7)

    for ev in filtered.itertuples(index=False):
        user_id = ev.user_id
        op = ev.op
        event_ts = ev.event_ts
        event_email = ev.email

        current = state.get(user_id)

        if op == "D":
            # Soft delete: email preserved if user exists, else fall back
            # to the event's email (new/unknown user case).
            if current is not None:
                preserved_email = current["email"]
            else:
                preserved_email = event_email
            state[user_id] = {
                "email": preserved_email,
                "status": "DELETED",
                "status_ts": event_ts,
            }
        elif op == "U":
            if current is None or current["status"] == "ACTIVE":
                state[user_id] = {
                    "email": event_email,
                    "status": "ACTIVE",
                    "status_ts": event_ts,
                }
            else:
                # current status is DELETED
                deletion_ts = current["status_ts"]
                if (event_ts - deletion_ts) > seven_days:
                    # Resurrection
                    state[user_id] = {
                        "email": event_email,
                        "status": "ACTIVE",
                        "status_ts": event_ts,
                    }
                # else: discard, no change
        else:
            # Unknown op: ignore (not specified by legacy semantics)
            pass

    # Build output dataframe
    out_rows = []
    for user_id, info in state.items():
        out_rows.append(
            {
                "user_id": user_id,
                "email": info["email"],
                "status": info["status"],
                "status_ts": info["status_ts"],
            }
        )

    new_snapshot = pd.DataFrame(
        out_rows, columns=["user_id", "email", "status", "status_ts"]
    )

    return {"new_snapshot": new_snapshot}
